mapper.select:
with filter as ( SELECT DISTINCT pr.id from po_reconciliation pr left join po_reconciliation_ref_detail prrd on pr.id = prrd.po_reconciliation_id and prrd.is_deleted = false left join po_reconciliation_detail prd on prrd.source_detail_id = prd.source_detail_id and prd.is_deleted = false left join foreign_purchase_order po on prrd.po_id = po.id and po.is_deleted = false where ${params.sqlMap.default} and prrd.is_deleted = false ) select
from po_reconciliation pr where pr.is_deleted = false and pr.id in (select id from filter)
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pr.id desc

